def git_blob(root: Path, path: str) -> str:
    result = subprocess.run(
        ["git", "-C", str(root), "hash-object", path],
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode:
        raise ValueError(f"git hash-object failed for {path}: {result.stderr.strip()}")
    return result.stdout.strip()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise ValueError(f"{label}: expected one preimage, found {count}")
    return text.replace(old, new, 1)


def apply(root: Path) -> list[dict[str, str]]:
    root = root.resolve()
    for path, expected in EXPECTED_GIT_BLOBS.items():
        actual = git_blob(root, path)
        if actual != expected:
            raise ValueError(f"{path}: expected Git blob {expected}, got {actual}")
    for path, expected in GENERATED_SHA256.items():
        actual = hashlib.sha256((root / path).read_bytes()).hexdigest()
        if actual != expected:
            raise ValueError(f"{path}: expected generated SHA-256 {expected}, got {actual}")

    receipts: list[dict[str, str]] = []
    for relative, edits in TRANSFORMS.items():
        path = root / relative
        before = path.read_text()
        after = before
        for label, old, new in edits:
            after = replace_once(after, old, new, label)
        if after == before:
            raise ValueError(f"{relative}: transformation was empty")
        path.write_text(after)
        receipts.append(
            {
                "path": relative,
                "before_sha256": hashlib.sha256(before.encode()).hexdigest(),
                "after_sha256": hashlib.sha256(after.encode()).hexdigest(),
            }
        )

    for relative, replacement in REPLACEMENT_FILES.items():
        path = root / relative
        before = path.read_text()
        path.write_text(replacement)
        receipts.append(
            {
                "path": relative,
                "before_sha256": hashlib.sha256(before.encode()).hexdigest(),
                "after_sha256": hashlib.sha256(replacement.encode()).hexdigest(),
            }
        )
    return receipts


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--receipt", type=Path)
    args = parser.parse_args()
    receipts = apply(args.root)
    output = json.dumps(
        {
            "schema": "hepta.memory-retrieval.phase-a-transform.v1",
            "files": receipts,
            "production_activation": False,
            "release": False,
        },
        indent=2,
        sort_keys=True,
    ) + "\n"
    if args.receipt is None:
        print(output, end="")
    else:
        args.receipt.write_text(output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
